'use strict';

// MODULES //

var dtypes = require( '@stdlib/ndarray/dtypes' );
var factory = require( '@stdlib/ndarray/base/nullary-strided1d-dispatch-factory' );
var drffti = require( '@stdlib/fft/base/fftpack/ndarray/float64/rffti' );
var srffti = require( '@stdlib/fft/base/fftpack/ndarray/float32/rffti' );
var grffti = require( '@stdlib/fft/base/fftpack/ndarray/generic/rffti' );
var DTYPES = require( './dtypes.js' ).odtypes;


// VARIABLES //

var idtypes0 = dtypes( 'integer_and_generic' );
var table = {
	'types': [
		'float64', // workspace
		'float32'  // workspace
	],
	'fcns': [
		drffti,
		srffti
	],
	'default': grffti
};


// MAIN //

/**
* Initializes a one-dimensional workspace ndarray for computing a real-valued discrete Fourier transform.
*
* @private
* @name rffti
* @type {Function}
* @param {ndarray} workspace - workspace ndarray
* @param {ndarray} N - zero-dimensional ndarray containing the sequence length
* @throws {TypeError} first argument must be an ndarray-like object
* @throws {TypeError} first argument must have a supported data type
* @throws {TypeError} second argument must be an ndarray-like object
* @throws {TypeError} options argument must be an object
* @throws {RangeError} dimension indices must not exceed input ndarray bounds
* @throws {RangeError} number of dimension indices must not exceed the number of input ndarray dimensions
* @throws {Error} must provide valid options
* @returns {ndarray} workspace ndarray
*
* @example
* var zeros = require( '@stdlib/ndarray/zeros' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
*
* var ws = zeros( [ 42 ], {
*     'dtype': 'float64'
* });
*
* var out = rffti( ws, scalar2ndarray( 4, {
*     'dtype': 'int32'
* }));
* // returns <ndarray>
*/
var rffti = factory( table, [ idtypes0 ], DTYPES );


// EXPORTS //

module.exports = rffti;
